function automatic ds_txn_t mk_ds(logic [ID_W-1:0] id, logic [ADDR_W-1:0] addr, logic [7:0] len, int size);
  ds_txn_t t;
  longint unsigned bb, total, first, last, dsz;
  bb = 64'd1 << size;
  total = (len+1)*bb - (addr - algn(addr,size));
  t.id = id; t.addr = addr; t.sbb = int'(bb);
  t.total_bytes = total;
  t.sal = algn(addr,size);
  t.dsize = (size<1)?size:1;
  dsz = 64'd1 << t.dsize; t.dbb = int'(dsz);
  t.dal = algn(addr, t.dsize);
  first = addr; last = addr + total - 1;
  t.dlen = int'((algn(last,t.dsize) - algn(first,t.dsize)) / dsz);
  return t;
endfunction
```

