  for (int i = mark; i < rb_all.size(); i++) begin
    logic [SDW-1:0] edata;
    logic [SDW/8-1:0] emask;
    logic [1:0] eresp;
    longint unsigned s0;
    longint unsigned A;
    if (rb_all[i].id != id) continue;
    edata = '0; emask = '0;
    s0 = t.sal + n * t.sbb;
    for (int l = 0; l < t.sbb; l++) begin
      A = s0 + l;
      if (A >= t.addr && A < t.addr + t.total) begin
        edata[(A % 8)*8 +: 8] = byte_val(A);
        emask[A % 8] = 1'b1;
      end
    end
    if (refused) eresp = 2'b10;
    else begin
      eresp = 2'b00;
      for (int k = 0; k <= t.dlen; k++)
        if (err_mask[k] && (((t.dal + k * t.dbb - t.sal) / t.sbb) <= n)) eresp = ecode;
    end
    for (int b = 0; b < 8; b++)
      if (emask[b] && rb_all[i].data[b*8 +: 8] != edata[b*8 +: 8])
        fail("D1/D2: upstream read data or lane mismatch");
    if (rb_all[i].resp != eresp)
      fail(refused ? "C4.4: refused read beat not SLVERR" : "D5/D6/D7: upstream read resp mismatch");
    if (rb_all[i].last != (n == ulen))
      fail("D4: s_rlast mismatch");
    n++;
  end
  if (n != ulen + 1)
    fail(refused ? "C4.5/A3: wrong number of R beats for refused read" : "A3: wrong number of upstream R beats");
endtask
```
